//! Cargo-driven `dpnet.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("dpnet-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/directx/wine/dpnet/dpnet_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "engine:oldnames", "import:ws2_32", "import:ole32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "x86_64" => &["dll/directx/wine/dpnet/dpnet_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "engine:oldnames", "import:ws2_32", "import:ole32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "aarch64" => &["dll/directx/wine/dpnet/dpnet_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "engine:oldnames", "import:ws2_32", "import:ole32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/dpnet",
        "dll/directx/wine/dpnet",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x600",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("dpnet_shims", &["dll/directx/wine/dpnet/address.c", "dll/directx/wine/dpnet/client.c", "dll/directx/wine/dpnet/dpnet_main.c", "dll/directx/wine/dpnet/lobbiedapp.c", "dll/directx/wine/dpnet/peer.c", "dll/directx/wine/dpnet/server.c", "dll/directx/wine/dpnet/threadpool.c"])
        .rc("dll/directx/wine/dpnet/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/dpnet/dpnet.spec", "dpnet.dll")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
